State2 = libsodium_crypto_xof_shake256:update(State1, <<"world">>),
{State3, First} = libsodium_crypto_xof_shake256:squeeze(State2, 16),
{_State4, Second} = libsodium_crypto_xof_shake256:squeeze(State3, 16),
Out = <<First/binary, Second/binary>>.
```
""".
